import os
import json
from typing import Any, Dict, List, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.formrecognizer import DocumentAnalysisClient


class AzureTableExtractor:
    def __init__(
        self,
        endpoint: Optional[str] = None,
        api_key: Optional[str] = None,
        model_id: str = "prebuilt-layout",
    ) -> None:
        self.endpoint = endpoint or os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
        self.api_key = api_key or os.environ["AZURE_FORM_RECOGNIZER_KEY"]
        self.model_id = model_id
        self.client = DocumentAnalysisClient(
            endpoint=self.endpoint,
            credential=AzureKeyCredential(self.api_key),
        )

    @staticmethod
    def _cell_polygon(cell: Any) -> Optional[List[Dict[str, float]]]:
        polygon = getattr(getattr(cell, "bounding_regions", [None])[0], "polygon", None)
        if not polygon:
            return None
        return [{"x": point.x, "y": point.y} for point in polygon]

    @staticmethod
    def _span_text(content: str, spans: Any) -> str:
        if not spans:
            return ""
        parts = []
        for span in spans:
            start = span.offset
            end = span.offset + span.length
            parts.append(content[start:end])
        return "".join(parts).strip()

    def extract_tables_from_bytes(
        self,
        document_bytes: bytes,
        content_type: str = "application/pdf",
    ) -> Dict[str, Any]:
        poller = self.client.begin_analyze_document(
            model_id=self.model_id,
            document=document_bytes,
            content_type=content_type,
        )
        result = poller.result()

        output: Dict[str, Any] = {
            "provider": "azure-document-intelligence",
            "model_id": self.model_id,
            "tables": [],
        }

        full_content = result.content or ""

        for table_idx, table in enumerate(result.tables or []):
            rows_map: Dict[int, List[Dict[str, Any]]] = {}

            for cell in table.cells:
                row_index = int(cell.row_index)
                col_index = int(cell.column_index)

                cell_data = {
                    "row_index": row_index,
                    "column_index": col_index,
                    "row_span": int(cell.row_span or 1),
                    "column_span": int(cell.column_span or 1),
                    "kind": str(cell.kind) if getattr(cell, "kind", None) else "content",
                    "content": (cell.content or "").strip(),
                    "text_from_spans": self._span_text(full_content, getattr(cell, "spans", None)),
                    "bounding_polygon": self._cell_polygon(cell),
                }

                rows_map.setdefault(row_index, []).append(cell_data)

            rows: List[Dict[str, Any]] = []
            for row_index in sorted(rows_map.keys()):
                cells = sorted(rows_map[row_index], key=lambda c: c["column_index"])
                rows.append(
                    {
                        "row_index": row_index,
                        "cells": cells,
                    }
                )

            table_data = {
                "table_index": table_idx,
                "row_count": int(table.row_count),
                "column_count": int(table.column_count),
                "rows": rows,
                "cells": [
                    cell
                    for row in rows
                    for cell in row["cells"]
                ],
            }
            output["tables"].append(table_data)

        return output

    def extract_tables_from_file(self, file_path: str) -> Dict[str, Any]:
        ext = os.path.splitext(file_path)[1].lower()
        content_type_map = {
            ".pdf": "application/pdf",
            ".png": "image/png",
            ".jpg": "image/jpeg",
            ".jpeg": "image/jpeg",
            ".tiff": "image/tiff",
            ".bmp": "image/bmp",
        }
        content_type = content_type_map.get(ext, "application/octet-stream")

        with open(file_path, "rb") as f:
            return self.extract_tables_from_bytes(f.read(), content_type=content_type)


def extract_table_cells_and_rows(file_path: str) -> Dict[str, Any]:
    extractor = AzureTableExtractor()
    return extractor.extract_tables_from_file(file_path)


if __name__ == "__main__":
    import sys

    result = extract_table_cells_and_rows(sys.argv[1])
    print(json.dumps(result, ensure_ascii=False, indent=2))
